{
  "segment_function": "Analyzing how homo faber's instrumentalization of nature leads to the degradation of things into means, the Greek contempt for banausic/utilitarian attitudes, the generalization of the fabrication experience, and Plato's critique of Protagoras's measure formula in favor of the divine standard.",
  "claims": [
    {
      "claim": "The instrumentalization inherent in homo faber implies a degradation of all things into means, stripping objects, nature, and the earth of their intrinsic and independent value because they lack reification from work.",
      "claim_type": "author_position",
      "supporting_excerpt": "Man, in so far as he is homo faber , instrumentalizes, and his instrumentalization implies a degradation of all things into means, their loss of intrinsic and independent value, so that eventually not only the objects of fabrication but also “the earth in general and all forces of nature,” which clearly came into being without the help of man and have an existence independent of the human world, lose their “value because [they] do not present the reification which comes from work.”",
      "support_kind": "direct",
      "qualifications": [
        "applies to man in so far as he is homo faber"
      ],
      "confidence": 1
    },
    {
      "claim": "The Greek classical period declared arts and crafts to be banausic or philistine because work with instruments was done for the sake of producing something else rather than for its own sake, reflecting vulgarity in expediency.",
      "claim_type": "historical_context",
      "supporting_excerpt": "It was for no other reason than this attitude of homo faber to the world that the Greeks in their classical period declared the whole field of the arts and crafts, where men work with instruments and do something not for its own sake but in order to produce something else, to be banausic , a term perhaps best translated by “philistine,” implying vulgarity of thinking and acting in terms of expediency.",
      "support_kind": "direct",
      "qualifications": [
        "limited to the Greeks in their classical period"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "banausic",
      "definition": "A term best translated by 'philistine,' implying vulgarity of thinking and acting in terms of expediency, applied by the classical Greeks to the field of arts and crafts where men work with instruments to produce something else."
    }
  ],
  "distinctions": [
    {
      "item_a": "instrumentality as a limited, productive process in fabrication",
      "item_b": "limitless instrumentalization driven by the life process taking hold of things",
      "distinction": "Fabrication treats the finished product as an end in itself, whereas when the life process takes hold of things for its purposes and the standards of homo faber rule unconditionally, instrumentality changes into limitless instrumentalization."
    }
  ],
  "must_not_be_lost": [
    "Plato's argument against Protagoras regarding 'man is the measure of all use things (chrēmata)'",
    "Plato's counter-formula that 'the god is the measure [even] of mere use objects' to combat the devaluation of world and nature."
  ]
}

